     "path": "email-entity-owner-notification.workflow-template.yaml",
     "kind": "Workflow",
     "url": "https://raw.githubusercontent.com/Dynatrace/community-examples/main/workflows/email-entity-owner-notification/email-entity-owner-notification.workflow-template.yaml",
