     "path": "rolebinding.yaml",
     "kind": "Workflow",
     "url": "https://raw.githubusercontent.com/Dynatrace/community-examples/main/workflows/kubernetes-stuck-pod-cleanup/rolebinding.yaml",
     "size": 314
